module ComfyUI.Assets.NodeTemplatesCQKDbCadJsMap

let file = """{"version":3,"file":"nodeTemplates-CQKDbCad.js","names":[],"sources":["../../src/extensions/core/nodeTemplates.ts"],"sourcesContent":["import { downloadBlob } from '@/base/common/downloadUtil'\nimport { t } from '@/i18n'\nimport type { IContextMenuValue } from '@/lib/litegraph/src/types/contextMenu'\nimport type { LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useDialogService } from '@/services/dialogService'\nimport type { ComfyExtension } from '@/types/comfy'\nimport { deserialiseAndCreate } from '@/utils/vintageClipboard'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nimport { api } from '../../scripts/api'\nimport { app } from '../../scripts/app'\nimport { ComfyDialog } from '../../scripts/ui'\nimport { $el } from '../../scripts/ui/utils'\n\n// Adds the ability to save and add multiple nodes as a template\n// To save:\n// Select multiple nodes (ctrl + drag to select a region or ctrl+click individual nodes)\n// Right click the canvas\n// Save Node Template -> give it a name\n//\n// To add:\n// Right click the canvas\n// Node templates -> click the one to add\n//\n// To delete/rename:\n// Right click the canvas\n// Node templates -> Manage\n//\n// To rearrange:\n// Open the manage dialog and Drag and drop elements using the \"Name:\" label as handle\n\nconst id = 'Comfy.NodeTemplates'\nconst file = 'comfy.templates.json'\n\ninterface NodeTemplate {\n  name: string\n  data: string\n}\n\nclass ManageTemplates extends ComfyDialog {\n  templates: NodeTemplate[] = []\n  draggedEl: HTMLElement | null\n  saveVisualCue: ReturnType<typeof setTimeout> | null\n  emptyImg: HTMLImageElement\n  importInput: HTMLInputElement\n\n  constructor() {\n    super()\n    void this.load().then((v) => {\n      this.templates = v\n    })\n\n    this.element.classList.add('comfy-manage-templates')\n    this.element.dataset.testid = 'manage-node-templates-dialog'\n    this.draggedEl = null\n    this.saveVisualCue = null\n    this.emptyImg = new Image()\n    this.emptyImg.src =\n      'data:image/gif;base64,R0lGODlhAQABAIAAAAUEBAAAACwAAAAAAQABAAACAkQBADs='\n\n    this.importInput = $el('input', {\n      type: 'file',\n      accept: '.json',\n      multiple: true,\n      style: { display: 'none' },\n      parent: document.body,\n      onchange: () => this.importAll()\n    })\n  }\n\n  override createButtons() {\n    const btns = super.createButtons()\n    btns[0].textContent = 'Close'\n    btns[0].onclick = () => {\n      if (this.saveVisualCue) clearTimeout(this.saveVisualCue)\n      this.close()\n    }\n    btns.unshift(\n      $el('button', {\n        type: 'button',\n        textContent: 'Export',\n        onclick: () => this.exportAll()\n      })\n    )\n    btns.unshift(\n      $el('button', {\n        type: 'button',\n        textContent: 'Import',\n        onclick: () => {\n          this.importInput.click()\n        }\n      })\n    )\n    return btns\n  }\n\n  async load() {\n    let templates = []\n    const res = await api.getUserData(file)\n    if (res.status === 200) {\n      try {\n        templates = await res.json()\n      } catch (error) {\n        reportError(error, {\n          surface: 'graph',\n          errorType: 'failure_loading_node_templates',\n          tags: {\n            failure_kind: 'caught_unexpected',\n            feature_area: 'extensions',\n            operation: 'load',\n            outcome: 'recovered'\n          },\n          level: 'error'\n        })\n      }\n    } else if (res.status !== 404) {\n      console.error(res.status + ' ' + res.statusText)\n    }\n    return templates ?? []\n  }\n\n  async store() {\n    const templates = JSON.stringify(this.templates, undefined, 4)\n    try {\n      await api.storeUserData(file, templates, { stringify: false })\n    } catch (error) {\n      console.error(error)\n      useToast().warning(t('toastMessages.failedToSaveNodeTemplates'), {\n        description: getErrorMessage(error) ?? t('g.unknownError')\n      })\n    }\n  }\n\n  async importAll() {\n    for (const file of this.importInput.files ?? []) {\n      if (file.type === 'application/json' || file.name.endsWith('.json')) {\n        const reader = new FileReader()\n        reader.onload = async () => {\n          const importFile = JSON.parse(reader.result as string)\n          if (importFile?.templates) {\n            for (const template of importFile.templates) {\n              if (template?.name && template?.data) {\n                this.templates.push(template)\n              }\n            }\n            await this.store()\n          }\n        }\n        await reader.readAsText(file)\n      }\n    }\n\n    this.importInput.value = ''\n\n    this.close()\n  }\n\n  exportAll() {\n    if (this.templates.length == 0) {\n      useToast().warning(t('toastMessages.noTemplatesToExport'))\n      return\n    }\n\n    const json = JSON.stringify({ templates: this.templates }, null, 2) // convert the data to a JSON string\n    const blob = new Blob([json], { type: 'application/json' })\n    downloadBlob('node_templates.json', blob)\n  }\n\n  override show() {\n    // Show list of template names + delete button\n    super.show(\n      $el(\n        'div',\n        {},\n        this.templates.flatMap((t, i) => {\n          let nameInput: HTMLInputElement\n          return [\n            $el(\n              'div',\n              {\n                dataset: { id: i.toString() },\n                className: 'templateManagerRow',\n                style: {\n                  display: 'grid',\n                  gridTemplateColumns: '1fr auto',\n                  border: '1px dashed transparent',\n                  gap: '5px',\n                  backgroundColor: 'var(--comfy-menu-bg)'\n                },\n                ondragstart: (e: DragEvent) => {\n                  const row = e.currentTarget\n                  if (!(row instanceof HTMLElement) || !e.dataTransfer) return\n                  this.draggedEl = row\n                  row.style.opacity = '0.6'\n                  row.style.border = '1px dashed yellow'\n                  e.dataTransfer.effectAllowed = 'move'\n                  e.dataTransfer.setDragImage(this.emptyImg, 0, 0)\n                },\n                ondragend: (e: DragEvent) => {\n                  const row = e.currentTarget\n                  if (!(row instanceof HTMLElement)) return\n                  row.style.opacity = '1'\n                  row.style.border = '1px dashed transparent'\n                  row.removeAttribute('draggable')\n\n                  // rearrange the elements\n                  this.element\n                    .querySelectorAll<HTMLElement>('.templateManagerRow')\n                    .forEach((el, i) => {\n                      const prev_i = Number.parseInt(el.dataset.id ?? '')\n\n                      if (el == this.draggedEl && prev_i != i) {\n                        this.templates.splice(\n                          i,\n                          0,\n                          this.templates.splice(prev_i, 1)[0]\n                        )\n                      }\n                      el.dataset.id = i.toString()\n                    })\n                  void this.store()\n                },\n                ondragover: (e: DragEvent) => {\n                  e.preventDefault()\n                  const row = e.currentTarget\n                  const draggedEl = this.draggedEl\n                  if (\n                    !(row instanceof HTMLElement) ||\n                    !row.parentNode ||\n                    !draggedEl\n                  )\n                    return\n                  if (row == this.draggedEl) return\n\n                  const rect = row.getBoundingClientRect()\n                  if (e.clientY > rect.top + rect.height / 2) {\n                    row.parentNode.insertBefore(draggedEl, row.nextSibling)\n                  } else {\n                    row.parentNode.insertBefore(draggedEl, row)\n                  }\n                }\n              },\n              [\n                $el(\n                  'label',\n                  {\n                    textContent: 'Name: ',\n                    style: {\n                      cursor: 'grab'\n                    },\n                    onmousedown: (e: MouseEvent) => {\n                      // enable dragging only from the label\n                      const label = e.currentTarget\n                      if (\n                        e.target instanceof HTMLLabelElement &&\n                        label instanceof HTMLLabelElement &&\n                        label.parentElement\n                      )\n                        label.parentElement.draggable = true\n                    }\n                  },\n                  [\n                    $el('input', {\n                      value: t.name,\n                      dataset: { name: t.name },\n                      style: {\n                        transitionProperty: 'background-color',\n                        transitionDuration: '0s'\n                      },\n                      onchange: (e: Event) => {\n                        const el = e.target\n                        if (!(el instanceof HTMLInputElement)) return\n                        if (this.saveVisualCue) clearTimeout(this.saveVisualCue)\n                        const row = el.closest<HTMLElement>(\n                          '.templateManagerRow'\n                        )\n                        if (!row) return\n                        this.templates[Number(row.dataset.id)].name =\n                          el.value.trim() || 'untitled'\n                        void this.store()\n                        el.style.backgroundColor = 'rgb(40, 95, 40)'\n                        el.style.transitionDuration = '0s'\n                        this.saveVisualCue = setTimeout(function () {\n                          el.style.transitionDuration = '.7s'\n                          el.style.backgroundColor = 'var(--comfy-input-bg)'\n                        }, 15)\n                      },\n                      onkeypress: (e: KeyboardEvent) => {\n                        const el = e.target\n                        if (!(el instanceof HTMLInputElement)) return\n                        if (this.saveVisualCue) clearTimeout(this.saveVisualCue)\n                        el.style.transitionDuration = '0s'\n                        el.style.backgroundColor = 'var(--comfy-input-bg)'\n                      },\n                      $: (el) => {\n                        if (el instanceof HTMLInputElement) nameInput = el\n                      }\n                    })\n                  ]\n                ),\n                $el('div', {}, [\n                  $el('button', {\n                    textContent: 'Export',\n                    style: {\n                      fontSize: '12px',\n                      fontWeight: 'normal'\n                    },\n                    onclick: () => {\n                      const json = JSON.stringify({ templates: [t] }, null, 2) // convert the data to a JSON string\n                      const blob = new Blob([json], {\n                        type: 'application/json'\n                      })\n                      const name = (nameInput.value || t.name) + '.json'\n                      downloadBlob(name, blob)\n                    }\n                  }),\n                  $el('button', {\n                    textContent: 'Delete',\n                    style: {\n                      fontSize: '12px',\n                      color: 'red',\n                      fontWeight: 'normal'\n                    },\n                    onclick: (e: MouseEvent) => {\n                      const target = e.target\n                      if (!(target instanceof HTMLElement)) return\n                      const item = target.closest<HTMLElement>(\n                        '.templateManagerRow'\n                      )\n                      if (!item) return\n                      item.remove()\n                      this.templates.splice(Number(item.dataset.id), 1)\n                      void this.store()\n                      // update the rows index, setTimeout ensures that the list is updated\n                      setTimeout(() => {\n                        this.element\n                          .querySelectorAll<HTMLElement>('.templateManagerRow')\n                          .forEach((el, i) => {\n                            el.dataset.id = i.toString()\n                          })\n                      }, 0)\n                    }\n                  })\n                ])\n              ]\n            )\n          ]\n        })\n      )\n    )\n  }\n}\n\nconst manage = new ManageTemplates()\n\nconst clipboardAction = async (cb: () => void | Promise<void>) => {\n  // We use the clipboard functions but dont want to overwrite the current user clipboard\n  // Restore it after we've run our callback\n  const old = localStorage.getItem('litegrapheditor_clipboard')\n  await cb()\n  if (old === null) localStorage.removeItem('litegrapheditor_clipboard')\n  else localStorage.setItem('litegrapheditor_clipboard', old)\n}\n\nconst ext: ComfyExtension = {\n  name: id,\n\n  getCanvasMenuItems(_canvas: LGraphCanvas): (IContextMenuValue | null)[] {\n    const items: (IContextMenuValue | null)[] = []\n\n    items.push(null)\n    items.push({\n      content: `Save Selected as Template`,\n      disabled: !Object.keys(app.canvas.selected_nodes).length,\n      callback: async () => {\n        const name = await useDialogService().prompt({\n          title: t('nodeTemplates.saveAsTemplate'),\n          message: t('nodeTemplates.enterName'),\n          defaultValue: ''\n        })\n        if (!name?.trim()) return\n\n        await clipboardAction(async () => {\n          app.canvas.copyToClipboard()\n          const data = localStorage.getItem('litegrapheditor_clipboard')\n\n          manage.templates.push({\n            name,\n            data: data || '{}'\n          })\n          await manage.store()\n        })\n      }\n    })\n\n    // Map each template to a menu item\n    const subItems: (IContextMenuValue | null)[] = manage.templates.map(\n      (template) => {\n        return {\n          content: template.name,\n          callback: async () => {\n            await clipboardAction(() => {\n              let data: { reroutes?: unknown }\n              try {\n                data = JSON.parse(template.data)\n              } catch (error) {\n                console.error('Failed to parse node template data', error)\n                useToast().warning(t('toastMessages.invalidTemplateData'))\n                return\n              }\n\n              // Check for old clipboard format\n              if (!data.reroutes) {\n                deserialiseAndCreate(template.data, app.canvas)\n              } else {\n                localStorage.setItem('litegrapheditor_clipboard', template.data)\n                app.canvas.pasteFromClipboard()\n              }\n            })\n          }\n        }\n      }\n    )\n\n    subItems.push(null, {\n      content: 'Manage',\n      callback: () => manage.show()\n    })\n\n    items.push({\n      content: 'Node Templates',\n      submenu: {\n        options: subItems\n      }\n    })\n\n    return items\n  }\n}\n\napp.registerExtension(ext)\n"],"mappings":"gbAiCA,IAAM,EAAK,sBACL,EAAO,uBAOP,gBAAN,cAA8B,CAAY,CACxC,UAA4B,CAAC,EAC7B,UACA,cACA,SACA,YAEA,aAAc,CACZ,MAAM,EACN,KAAU,KAAK,CAAC,CAAC,KAAM,GAAM,CAC3B,KAAK,UAAY,CACnB,CAAC,EAED,KAAK,QAAQ,UAAU,IAAI,wBAAwB,EACnD,KAAK,QAAQ,QAAQ,OAAS,+BAC9B,KAAK,UAAY,KACjB,KAAK,cAAgB,KACrB,KAAK,SAAW,IAAI,MACpB,KAAK,SAAS,IACZ,yEAEF,KAAK,YAAc,EAAI,QAAS,CAC9B,KAAM,OACN,OAAQ,QACR,SAAU,GACV,MAAO,CAAE,QAAS,MAAO,EACzB,OAAQ,SAAS,KACjB,aAAgB,KAAK,UAAU,CACjC,CAAC,CACH,CAEA,eAAyB,CACvB,IAAM,EAAO,MAAM,cAAc,EAsBjC,MArBA,GAAK,EAAE